const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_PATH = join(__dirname, 'data', 'word-dari.json');

/** Preserve special key casing; otherwise lowercase. */
function normalizeKey(word) {
  const special = new Set(['Wi-Fi', 'URL', 'CV', 'God', 'main idea']);
  if (special.has(word)) return word;
  return word.toLowerCase();
}

function parseWords(str) {
  return str.split(',').map((w) => w.trim()).filter(Boolean);
}

function take(words, n) {
  return words.slice(0, n);
}

