// Validate every word in the ordered curriculum list
const missing = [];
for (const word of ORDERED) {
  const key = normalizeKey(word);
  if (!(key in LEX)) missing.push(key);
}
if (missing.length) {
  throw new Error(`Missing ${missing.length} LEX entries: ${missing.slice(0, 20).join(', ')}${missing.length > 20 ? '…' : ''}`);
}

// Build output JSON (unique keys from LEX used in curriculum + sample extras)
const sampleExtras = ['scholarship', 'mentor'];
const outputKeys = new Set([...ORDERED.map(normalizeKey), ...sampleExtras]);
const output = {};
for (const key of [...outputKeys].sort()) {
  if (key in LEX) output[key] = LEX[key];
}

mkdirSync(dirname(OUT_PATH), { recursive: true });
writeFileSync(OUT_PATH, `${JSON.stringify(output, null, 2)}\n`, 'utf8');

console.log(`Wrote ${Object.keys(output).length} entries → ${OUT_PATH}`);
